#[verifier::spec]
fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> Vec<f64> {
    // Precondition: The indices array must be non-empty and the choices matrix must have at least one row.
    // Each row in choices must be non-empty and have the same length as indices.
    // Each index in indices must be a valid row selector for choices.
    requires(!indices.is_empty());
    requires(!choices.is_empty());
    requires(choices.iter().all(|row| !row.is_empty()));
    requires(choices.iter().all(|row| row.len() == indices.len()));
    requires(indices.iter().all(|&index| index < choices.len() as u8));

    // The length of the result must be equal to the length of the indices array.
    let result: Vec<f64> = vec![0.0; indices.len()];

    // Invariant: For each index i, the result[i] is assigned the value from choices at the specified row and column.
    // The column is determined by the index of the current iteration.
    // The index for the row is given by indices[i].
    // This loop will iterate over each index in the indices array.
    let n = indices.len();
    ensures(result.len() == n);
    ensures(result.iter().enumerate().all(|(i, &val)| val == choices[indices[i] as usize][i]));

    // Decreases clause: The loop will iterate n times, where n is the length of indices.
    decreases(n);

    // Loop to populate the result array.
    for i in 0..n {
        // Assign the value from the choices matrix to the result array.
        result[i] = choices[indices[i] as usize][i];
    }

    // Return the constructed result array.
    result
}